+            Map<String, Object> body = JsonReader.object(source, indicatorId);
+            months.put(
+                    indicatorId,
+                    new ComparisonMonths(
+                            indicatorId,
+                            JsonReader.months(body, "months"),
+                            JsonReader.months(body, "omitted")));
+        }
+        return Map.copyOf(months);
+    }
